// Demo: Signature Metamorphic Engine Detection — entropy flags packed code
function entropy(s){var f={},h=0;for(var i=0;i<s.length;i++){f[s[i]]=(f[s[i]]||0)+1;}
Object.keys(f).forEach(function(k){var p=f[k]/s.length;h-=p*Math.log2(p);});return h;}
var plain='function hello(){return 42;}//'.repeat(20);
var packed='';for(var i=0;i<plain.length;i++){packed+=String.fromCharCode(32+((i*7919+1)%95));}
console.log('technique: Signature Metamorphic Engine Detection');console.log('plain entropy: '+entropy(plain).toFixed(2)+', packed entropy: '+entropy(packed).toFixed(2));
console.log(entropy(packed)>6.5?'packed/encrypted section flagged':'entropy normal');

